function detectionMarkup(company){
  const mapping=[['name','Nom',company.legalName||company.name],['siren','SIREN',company.siren],['siret','SIRET',company.siret],['legalForm','Forme juridique',company.legalForm||company.legal_form],['address','Adresse',company.address],['postalCode','Code postal',company.postalCode||company.postal_code],['city','Ville',company.city],['website','Site internet',company.website],['activity','Activité',company.activity]];
  return `<div class="journey-detection"><p><strong>Données trouvées — source : ${esc(company.source||'service de recherche d’entreprise')}</strong></p>${mapping.filter(([, ,v])=>String(v||'').trim()).map(([key,label,v])=>{const field=document.querySelector(`#j-${key==='legalForm'?'legal-form':key}`);const existing=field?.value?.trim()||'';const conflict=existing&&existing!==String(v);return `<div class="journey-detection-row"><span>${esc(label)}</span><span>${esc(v)}</span>${conflict?`<label><input type="checkbox" data-detected-field="${esc(key)}"> Remplacer la valeur existante</label>`:`<span class="help">${existing?'Identique':'Champ à compléter'}</span>`}</div>`}).join('')}<div class="button-row"><button type="button" class="btn primary small" id="journey-apply-detection">Appliquer les données choisies</button><button type="button" class="btn secondary small" id="journey-close-detection">Fermer</button></div></div>`;
}
