      <div class="grid-2">${colorChoiceField('j-brand-accent','Couleur principale personnalisée',s.accent||t.accent,['#2563EB','#0D9488','#7C3AED','#EA580C','#DB2777','#CA8A04','#0891B2','#111827'])}${colorChoiceField('j-brand-dark','Couleur sombre personnalisée',s.dark||t.dark,['#111827','#172554','#052E2B','#2E1065','#431407','#3F1D2D','#1F2937','#FFFFFF'])}</div>
