  document.querySelector('#journey-next').onclick=async()=>{if(transitionBusy||saving)return;if(currentStep!==7){await moveTo(nextJourneyStep(currentStep,businessStatus()));return;}transitionBusy=true;try{if(!await persist({recordEvent:true}))return;if(checked('j-sig-save')){const sigPayload={enabled:true,firstName:value('j-sig-first'),lastName:value('j-sig-last'),jobTitle:value('j-sig-role'),company:value('j-sig-email-company'),phone:value('j-sig-phone'),website:value('j-sig-website'),address:value('j-sig-address'),extra:value('j-sig-extra'),includeQuotes:checked('j-sig-quote'),includeInvoices:checked('j-sig-invoice'),includeProfessional:checked('j-sig-professional')};await api.saveEmailSignature(sigPayload);}await api.completeJourney();journey.status='completed';saveStatus('Configuration enregistrée ; ouverture du tableau de bord…');toast('Configuration enregistrée. Ouverture du tableau de bord Aurion.','success');setTimeout(()=>go('/dashboard'),150);}catch(e){toast(e.message||'Impossible de finaliser la configuration.','error')}finally{transitionBusy=false;}};
  document.querySelector('#journey-prev').onclick=()=>moveTo(previousJourneyStep(currentStep,businessStatus()));
  document.querySelector('#journey-skip').onclick=async()=>{if(transitionBusy||saving)return;transitionBusy=true;try{const from=currentStep,skipped=[...(data.skippedSteps||[]),from].filter((n,i,a)=>a.indexOf(n)===i),nextStep=nextJourneyStep(from,businessStatus());data={...data,skippedSteps:skipped};setSaved(from,{...collectStep(),skipped:true});if(!await persist({recordEvent:true,targetStep:nextStep,collectCurrent:false}))return;currentStep=nextStep;journey.currentStep=nextStep;renderStep()}finally{transitionBusy=false;}};
  document.querySelector('#journey-later').onclick=pauseAndExit;
  document.querySelector('#journey-dashboard').onclick=pauseAndExit;document.querySelector('.journey-header .brand')?.addEventListener('click',ev=>{ev.preventDefault();pauseAndExit()});document.querySelector('#journey-admin-reload')?.addEventListener('click',async()=>{await reloadSupportingData();renderStep()});
  document.querySelector('#journey-retry-save')?.addEventListener('click',()=>persist().catch(()=>{}));
