    setSaved(2,s2);setSaved(3,s3);try{await saveOrganizationPatch({name:s2.name,activity:s2.activity,customActivity:s2.customActivity,siren:s2.siren,siret:s2.siret,legalForm:s2.legalForm,website:s2.website,address:s2.address,postalCode:s2.postalCode,city:s2.city,configurationIncomplete:true});if(selected.formalityTitle){const title=document.querySelector('#j-formality-title');if(title)title.value=selected.formalityTitle;}if(selected.organization){const field=document.querySelector('#j-formality-org');if(field)field.value=selected.organization;}if(selected.nextAction){const field=document.querySelector('#j-formality-next');if(field)field.value=selected.nextAction;}if(selected.notes){const field=document.querySelector('#j-formality-notes');if(field)field.value=selected.notes;}await persist();toast('Les champs sélectionnés ont été préremplis. Vérifiez-les avant de continuer.','success');}catch(e){toast(e.message||'Les champs n’ont pas pu être enregistrés.','error');}
