  document.querySelectorAll('[data-ignore-mail]').forEach(btn=>btn.onclick=async()=>{try{await api.updateAdministrativeMailItem(btn.dataset.ignoreMail,{ignore:true});await reloadSupportingData();renderStep();toast('Message ignoré ; historique conservé.','info')}catch(e){toast(e.message||'Action impossible.','error')}});
